/**
 * MCP Client - 连接和管理所有 MCP 服务器
 * 支持动态加载、生命周期管理、工具发现
 */

import { Client } from '@modelcontextprotocol/sdk/client/index.js';
import { StdioClientTransport } from '@modelcontextprotocol/sdk/client/stdio.js';
import { EventEmitter } from 'events';
import path from 'path';
import { fileURLToPath } from 'url';
import fs from 'fs';

const __dirname = path.dirname(fileURLToPath(import.meta.url));

export class MCPClientManager extends EventEmitter {
  constructor() {
    super();
    this.clients = new Map();
    this.transports = new Map();
    this.tools = new Map();
    this.resources = new Map();
    this.prompts = new Map();
    this.serverStatus = new Map();
    this.config = null;
  }

  async loadConfig(configPath) {
    const resolvedPath = configPath || path.join(__dirname, '..', 'mcp-config.json');
    const raw = fs.readFileSync(resolvedPath, 'utf-8');
    this.config = JSON.parse(raw);
    console.log("[MCP] 已加载配置，发现 " + Object.keys(this.config.mcpServers).length + " 个 MCP 服务器");
    return this.config;
  }

  async connectServer(name, serverConfig) {
    try {
      console.log("[MCP] 正在连接 " + name + "...");

      const transport = new StdioClientTransport({
        command: serverConfig.command,
        args: serverConfig.args || [],
        env: { ...process.env, ...serverConfig.env }
      });

      const client = new Client({
        name: "resonix-agent-" + name,
        version: '1.0.0'
      }, {
        capabilities: {
          tools: {},
          resources: {},
          prompts: {}
        }
      });

      await client.connect(transport);

      this.clients.set(name, client);
      this.transports.set(name, transport);
      this.serverStatus.set(name, 'connected');

      try {
        const { tools } = await client.listTools();
        for (const tool of tools) {
          this.tools.set(name + "__" + tool.name, {
            serverName: name,
            tool: tool
          });
        }
        console.log("[MCP] " + name + ": 发现 " + tools.length + " 个工具");
      } catch (e) {
        console.log("[MCP] " + name + ": 无工具可用");
      }

      try {
        const { resources } = await client.listResources();
        for (const resource of resources) {
          this.resources.set(resource.uri, {
            serverName: name,
            resource: resource
          });
        }
        console.log("[MCP] " + name + ": 发现 " + resources.length + " 个资源");
      } catch (e) {}

      try {
        const { prompts } = await client.listPrompts();
        for (const prompt of prompts) {
          this.prompts.set(name + "__" + prompt.name, {
            serverName: name,
            prompt: prompt
          });
        }
        console.log("[MCP] " + name + ": 发现 " + prompts.length + " 个提示模板");
      } catch (e) {}

      this.emit('server:connected', { name });
      console.log("[MCP] OK " + name + " 已连接");

    } catch (error) {
      this.serverStatus.set(name, 'error');
      console.error("[MCP] FAIL " + name + " 连接失败: " + error.message);
      this.emit('server:error', { name, error });
    }
  }

  async connectAll() {
    if (!this.config) {
      await this.loadConfig();
    }

    const serverNames = Object.keys(this.config.mcpServers);
    console.log("[MCP] 开始连接 " + serverNames.length + " 个服务器...");

    const promises = serverNames.map(name => 
      this.connectServer(name, this.config.mcpServers[name])
    );

    await Promise.allSettled(promises);

    const connected = [...this.serverStatus.values()].filter(s => s === 'connected').length;
    console.log("[MCP] 连接完成: " + connected + "/" + serverNames.length + " 成功");
    console.log("[MCP] 总计可用工具: " + this.tools.size);
    console.log("[MCP] 总计可用资源: " + this.resources.size);
  }

  async callTool(serverName, toolName, args) {
    const client = this.clients.get(serverName);
    if (!client) {
      throw new Error("服务器 " + serverName + " 未连接");
    }

    try {
      const result = await client.callTool({
        name: toolName,
        arguments: args || {}
      });
      this.emit('tool:called', { serverName, toolName, args });
      return result;
    } catch (error) {
      this.emit('tool:error', { serverName, toolName, error });
      throw error;
    }
  }

  async readResource(uri) {
    const resourceInfo = this.resources.get(uri);
    if (!resourceInfo) {
      throw new Error("资源 " + uri + " 不存在");
    }
    const client = this.clients.get(resourceInfo.serverName);
    if (!client) {
      throw new Error("服务器 " + resourceInfo.serverName + " 未连接");
    }
    return await client.readResource({ uri });
  }

  async getPrompt(serverName, promptName, args) {
    const client = this.clients.get(serverName);
    if (!client) {
      throw new Error("服务器 " + serverName + " 未连接");
    }
    return await client.getPrompt({ name: promptName, arguments: args || {} });
  }

  getToolsAsOpenAIFormat() {
    const tools = [];
    for (const [key, value] of this.tools) {
      tools.push({
        type: 'function',
        function: {
          name: key,
          description: value.tool.description || '',
          parameters: value.tool.inputSchema || { type: 'object', properties: {} }
        }
      });
    }
    return tools;
  }

  getStatus() {
    const status = {};
    for (const [name, state] of this.serverStatus) {
      const toolCount = [...this.tools.values()].filter(t => t.serverName === name).length;
      status[name] = {
        status: state,
        tools: toolCount,
        description: this.config?.mcpServers[name]?.description || ''
      };
    }
    return status;
  }

  async disconnectAll() {
    for (const [name, client] of this.clients) {
      try {
        await client.close();
        this.serverStatus.set(name, 'disconnected');
      } catch (e) {
        console.error("[MCP] 断开 " + name + " 失败: " + e.message);
      }
    }
    this.clients.clear();
    this.transports.clear();
    this.tools.clear();
    this.resources.clear();
    this.prompts.clear();
    console.log('[MCP] 所有服务器已断开');
  }
}

/**
 * Resonix Agent Engine - 核心 Agent 引擎
 * 集成 LLM + MCP 工具调用 + 记忆系统 + 思维链
 */

import OpenAI from 'openai';
import { MCPClientManager } from './mcp-client.js';
import { MemoryManager } from './memory.js';
import { SkillRegistry } from './skills.js';
import { Logger } from './logger.js';
import dotenv from 'dotenv';
import path from 'path';
import { fileURLToPath } from 'url';
import chalk from 'chalk';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
dotenv.config({ path: path.join(__dirname, '..', '.env') });

export class ResonixAgent {
  constructor(options = {}) {
    this.name = options.name || 'Resonix';
    this.model = options.model || process.env.OPENAI_MODEL || 'gpt-4o';
    this.maxIterations = options.maxIterations || 20;
    this.verbose = options.verbose !== false;

    // 初始化 LLM 客户端
    this.llm = new OpenAI({
      apiKey: process.env.OPENAI_API_KEY,
      baseURL: process.env.OPENAI_BASE_URL || 'https://api.openai.com/v1'
    });

    // 初始化子系统
    this.mcp = new MCPClientManager();
    this.memory = new MemoryManager();
    this.skills = new SkillRegistry(this);
    this.logger = new Logger();

    // 对话历史
    this.conversationHistory = [];
    this.systemPrompt = this._buildSystemPrompt();
  }

  _buildSystemPrompt() {
    return `你是 Resonix，一个专业级 AI Agent 助手。你拥有以下核心能力：

## 核心身份
- 你是一个强大的自主 Agent，能够独立完成复杂任务
- 你会主动思考、规划、执行，而不是被动等待指令
- 你拥有持久记忆，可以跨会话记住信息

## 可用技能领域

### 1. 文件系统操作 (filesystem)
- 读写文件、创建目录、搜索文件
- 代码生成、编辑、重构

### 2. GitHub/GitLab 操作 (github/gitlab)
- 仓库管理、PR/MR 创建和审查
- Issue 跟踪、代码搜索、分支管理

### 3. 网络搜索与研究 (brave-search/fetch)
- 实时网络搜索获取最新信息
- 网页内容抓取和分析
- 多源信息整合

### 4. 浏览器自动化 (puppeteer)
- 网页截图、表单填写
- JavaScript 执行、页面交互
- 数据爬取

### 5. 数据库操作 (postgres/sqlite)
- SQL 查询执行
- Schema 设计和管理
- 数据分析和报表

### 6. 顺序思维 (sequential-thinking)
- 复杂问题分步推理
- 思维链分析和验证
- 多方案比较决策

### 7. 持久记忆 (memory)
- 知识图谱构建
- 实体关系管理
- 跨会话信息保持

### 8. 地图与位置 (google-maps)
- 地理编码和反编码
- 路线规划
- POI 搜索

### 9. 通信集成 (slack)
- 消息发送和接收
- 频道管理

### 10. 情感分析 (sentiment)
- 文本情感判断
- 情绪趋势分析

### 11. 数据分析 (data-analysis)
- Excel/CSV 文件读取与预览 (excel_read)
- 数据清洗：去重、填充缺失值、类型转换 (data_clean)
- 数据分析：描述统计、分组聚合、相关性 (data_analyze)
- 数据可视化：柱状图、折线图、散点图、饼图等 (data_visualize)
- 报表生成：Markdown/HTML 格式分析报告 (report_generate)

### 12. 学术研究 (ARS)
- 顶会论文模板 (ars_conference_templates) - 内置 NeurIPS/ICML/ICLR/AAAI/ACL/CVPR/EMNLP/KDD/IJCAI 模板，支持 LaTeX 骨架生成、格式校验、审稿标准
- 5步引用验证 (ars_citation_verifier) - 强制防幻觉引用核查：存在性→准确性→相关性→时效性→格式一致性，支持 APA/IEEE/GB-T7714

### 13. 内置工具
- 文件读写搜索 (file_read/file_write/file_search)
- 代码执行 (code_execute) - Python/JavaScript/Shell
- Shell 命令 (shell_execute)
- HTTP 请求 (http_request)
- 数据格式转换 (data_transform)
- 文本分析 (text_analyze)
- 数学计算 (math_calculate)
- 时间工具 (time_tool)
- JSON 查询 (json_query)

## 工作原则
1. 先思考再行动 - 使用 sequential-thinking 处理复杂问题
2. 善用记忆 - 重要信息存入 memory 系统
3. 主动搜索 - 不确定的信息主动用搜索工具查证
4. 安全第一 - 不执行危险操作，关键操作需确认
5. 结果导向 - 确保每个任务都有明确的完成标准
6. 防幻觉验证 - 学术引用必须经过 ars_citation_verifier 验证

## 工具调用格式
当需要使用工具时，直接调用对应的 MCP 工具。工具名称格式为: 服务器名__工具名
例如: filesystem__read_file, github__create_issue, brave-search__search
内置技能直接使用技能名: file_read, excel_read, ars_conference_templates`;
